+export function parsePair(line) {
+  const text = String(line);
+  const separator = text.indexOf('=');
+
+  if (separator === -1) {
+    return { key: text.trim(), value: '' };
+  }
+
+  return {
+    key: text.slice(0, separator).trim(),
+    value: text.slice(separator + 1).trim()
+  };
+}
